require_once __DIR__.'/../includes/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('admin/users.php');verify_csrf();$id=(int)($_POST['id']??0);if($id<=0||$id===(int)current_user()['id']){set_flash('error','You cannot delete your own account.');redirect('admin/users.php');}$s=db()->prepare('SELECT profile_picture FROM users WHERE id=?');$s->execute([$id]);$u=$s->fetch();if(!$u)set_flash('error','User not found.');else{$s=db()->prepare('DELETE FROM users WHERE id=?');$s->execute([$id]);if($u['profile_picture']&&is_file(__DIR__.'/../'.$u['profile_picture']))@unlink(__DIR__.'/../'.$u['profile_picture']);set_flash('success','User deleted.');}redirect('admin/users.php');
